import{_ as d,o as e,c as r,ag as a}from"./chunks/framework.C5oN-8Wt.js";const b=JSON.parse('{"title":"GNSS 接收机","description":"","frontmatter":{},"headers":[],"relativePath":"v0.5.0-beta/modules/gnss_receiver/index.md","filePath":"v0.5.0-beta/modules/gnss_receiver/index.md"}'),o={name:"v0.5.0-beta/modules/gnss_receiver/index.md"};function c(n,t,h,i,l,s){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="gnss-接收机" tabindex="-1">GNSS 接收机 <a class="header-anchor" href="#gnss-接收机" aria-label="Permalink to &quot;GNSS 接收机&quot;">​</a></h1><h2 id="它做什么" tabindex="-1">它做什么 <a class="header-anchor" href="#它做什么" aria-label="Permalink to &quot;它做什么&quot;">​</a></h2><p>GNSS 接收机读取录制的 GPS 信号，捕获并跟踪卫星信号，结合导航电文和信号传播时间求出接收机的位置。每次求得位置时，会给出该时刻的经纬度、高程和相对首个定位点的东向、北向偏移。</p><h2 id="接线" tabindex="-1">接线 <a class="header-anchor" href="#接线" aria-label="Permalink to &quot;接线&quot;">​</a></h2><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>recording</code>（录制文件）</td><td><code>gnss_recording</code></td><td>文件引用</td></tr><tr><td>输出</td><td><code>latitude</code>（纬度）</td><td><code>numeric_f64</code></td><td>°；vlen=1</td></tr><tr><td>输出</td><td><code>longitude</code>（经度）</td><td><code>numeric_f64</code></td><td>°；vlen=1</td></tr><tr><td>输出</td><td><code>height</code>（高程）</td><td><code>numeric_f64</code></td><td>m；vlen=1</td></tr><tr><td>输出</td><td><code>east</code>（东向偏移）</td><td><code>numeric_f64</code></td><td>m；vlen=1</td></tr><tr><td>输出</td><td><code>north</code>（北向偏移）</td><td><code>numeric_f64</code></td><td>m；vlen=1</td></tr></tbody></table><p>把 <a href="./../gnss_recording_source/">GNSS 录制信号源</a>的“录制文件”输出接到本模块。两路水平偏移来自同一个定位时刻，可以绑定到观察器的 XY 关系图。</p><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>多普勒搜索上限 (Hz)<br><code>doppler_max</code></td><td><code>10000</code></td><td>范围 500 至 20000</td><td>重新准备</td></tr><tr><td>多普勒搜索步进 (Hz)<br><code>doppler_step</code></td><td><code>250</code></td><td>范围 50 至 1000</td><td>重新准备</td></tr><tr><td>载波跟踪带宽 (Hz)<br><code>pll_bw_hz</code></td><td><code>40</code></td><td>范围 1 至 100</td><td>重新准备</td></tr></tbody></table><table tabindex="0"><thead><tr><th>参数</th><th>怎样理解</th></tr></thead><tbody><tr><td>多普勒搜索上限</td><td>决定捕获时在名义频率两侧各搜索多宽。</td></tr><tr><td>多普勒搜索步进</td><td>决定相邻候选频率隔多少 Hz。步进越小，接收机会检查越多候选频率。</td></tr><tr><td>载波跟踪带宽</td><td>决定捕获后跟踪环跟随载波变化的速度。带宽加宽时，能跟随更快的变化，也会接收更多噪声。</td></tr></tbody></table><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>在<a href="./../../learn/recorded-gnss/">录制信号定位</a>里先用默认参数得到一轮位置，再改变多普勒搜索步进，观察同一段录制信号的定位结果。</p>',14)])])}const p=d(o,[["render",c]]);export{b as __pageData,p as default};
